"""Phase 0: compute per-rule token costs without LLM calls.

Loads each rule, applies it to every document, and counts tokens in the
retrieved text using tiktoken.  No QA or judge LLM calls are made.

Output schema per rule:
    {
        "W": <total retrieved tokens across all docs>,
        "per_doc": {doc_name: retrieved_token_count, ...},
        "per_doc_ratio": {doc_name: retrieved / total_doc_tokens, ...},
        "avg_cost_ratio": <mean of per_doc_ratio values>
    }
"""

from __future__ import annotations

import importlib.util
import json
from pathlib import Path


def _count_tokens(text: str) -> int:
    try:
        import tiktoken
        enc = tiktoken.get_encoding("cl100k_base")
        return len(enc.encode(text))
    except Exception:
        return int(len(text.split()) * 1.3)


def _load_rule_fn(rule_file: Path):
    spec = importlib.util.spec_from_file_location("_rule_mod", str(rule_file))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    try:
        return next(v for k, v in vars(mod).items() if k.startswith("rule_") and callable(v))
    except StopIteration:
        raise ValueError(f"No function starting with 'rule_' found in {rule_file}")


def compute_rule_costs(
    rules_dir: str,
    doc_paths: list[Path],
) -> dict[str, dict]:
    """Return cost profile for every rule_*.py in rules_dir. No LLM calls."""
    rules_path = Path(rules_dir)
    rule_files = sorted(rules_path.glob("rule_*.py"))
    if not rule_files:
        raise FileNotFoundError(f"No rule_*.py files found in {rules_dir}")

    result: dict[str, dict] = {}

    for rule_file in rule_files:
        rule_name = rule_file.stem
        try:
            rule_fn = _load_rule_fn(rule_file)
        except Exception as exc:
            print(f"  WARNING: skipping {rule_name}: {exc}")
            continue

        per_doc: dict[str, int] = {}
        per_doc_ratio: dict[str, float] = {}
        W = 0

        for doc_path in doc_paths:
            doc_name = doc_path.stem.replace("_reconstructed", "")
            try:
                doc = json.loads(doc_path.read_text(encoding="utf-8"))
            except Exception:
                continue

            total_doc_tokens = _count_tokens(
                "\n".join(s.get("text", "") for s in doc.get("texts", []))
            )

            try:
                spans = rule_fn(doc)
            except Exception:
                spans = []

            retrieved_text = "\n\n".join(s["text"] for s in spans) if spans else ""
            retrieved_tokens = _count_tokens(retrieved_text)

            per_doc[doc_name] = retrieved_tokens
            W += retrieved_tokens
            if total_doc_tokens > 0:
                per_doc_ratio[doc_name] = retrieved_tokens / total_doc_tokens

        avg_cost_ratio = (
            sum(per_doc_ratio.values()) / len(per_doc_ratio) if per_doc_ratio else 0.0
        )

        result[rule_name] = {
            "W": W,
            "per_doc": per_doc,
            "per_doc_ratio": per_doc_ratio,
            "avg_cost_ratio": round(avg_cost_ratio, 6),
        }

    return result


def load_or_compute_cost_profile(
    rules_dir: str,
    doc_paths: list[Path],
    cache_path: Path | None = None,
) -> dict[str, dict]:
    """Return cost profile from cache_path if it exists, else compute and optionally cache."""
    if cache_path is not None and cache_path.exists():
        return json.loads(cache_path.read_text(encoding="utf-8"))

    profile = compute_rule_costs(rules_dir, doc_paths)

    if cache_path is not None:
        cache_path.parent.mkdir(parents=True, exist_ok=True)
        cache_path.write_text(
            json.dumps(profile, indent=2, ensure_ascii=False), encoding="utf-8"
        )

    return profile

def rule_page1_near_trading_symbol_label(doc: dict) -> list[dict]:
    """Match spans within a small window around a page 1 'Trading Symbol' label."""
    try:
        import re
        texts = doc.get("texts", [])
        out = []
        for i, span in enumerate(texts):
            txt = (span.get("text") or "")
            if span.get("page_no") == 1 and re.search(r"trading symbol", txt, re.I):
                for j in range(max(0, i - 3), min(len(texts), i + 6)):
                    s = texts[j]
                    t = (s.get("text") or "")
                    if re.search(r"trading symbol|exchange|registered", t, re.I) or re.fullmatch(r"[A-Z]{1,8}(?:\d+[A-Z]{0,3})?", t.strip()):
                        out.append(s)
        return out
    except Exception:
        return []

def rule_business_sentence_trades_on_exchange(doc: dict) -> list[dict]:
    """Match business-description sentences saying common stock trades/listed on an exchange under a symbol."""
    try:
        import re
        out = []
        for span in doc.get("texts", []):
            txt = (span.get("text") or "")
            if re.search(r"common stock.*?(trades|traded|listed).*?(nasdaq|new york stock exchange|nyse).*?symbol", txt, re.I):
                out.append(span)
        return out
    except Exception:
        return []

def rule_page1_registration_block_all(doc: dict) -> list[dict]:
    """Return all page 1 spans from the first 12(b) registration mention until the 12(g) mention or end of top block."""
    try:
        import re
        texts = doc.get("texts", [])
        start = None
        end = None
        for i, span in enumerate(texts):
            txt = (span.get("text") or "")
            if start is None and span.get("page_no") == 1 and re.search(r"section\s+12\(b\)|12\(b\)\s+of\s+the\s+act", txt, re.I):
                start = i
            if start is not None and span.get("page_no") == 1 and re.search(r"section\s+12\(g\)|12\(g\)\s+of\s+the\s+act", txt, re.I):
                end = i
                break
        if start is None:
            return []
        if end is None:
            end = min(len(texts), start + 20)
        return [s for s in texts[start:end] if s.get("page_no") == 1]
    except Exception:
        return []

